/* ============== Calculator ============== */
function Slider({ label, value, min, max, step, format, onChange }) {
  const pct = ((value - min) / (max - min)) * 100;
  return (
    <div className="mk-slider">
      <div className="mk-slider-row">
        <span className="mk-slider-l">{label}</span>
        <span className="mk-slider-v">{format(value)}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        className="mk-slider-i"
        style={{ background: `linear-gradient(to right, var(--fg-0) 0%, var(--fg-0) ${pct}%, var(--line-2) ${pct}%, var(--line-2) 100%)` }}
      />
      <div className="mk-slider-ticks">
        <span>{format(min)}</span>
        <span>{format(max)}</span>
      </div>
    </div>
  );
}

export function Calculator() {
  const [ticket, setTicket] = useState(350);
  const [calls, setCalls] = useState(25);
  const [missRate, setMissRate] = useState(30);
  const annual = ticket * calls * 365 * (missRate / 100);
  const monthly = annual / 12;
  const missedDaily = calls * (missRate / 100);
  const missedMonthly = missedDaily * 30;

  const calcRef = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = calcRef.current;
    if (!el) return;
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) { setVisible(true); io.disconnect(); } });
    }, { threshold: 0.2 });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <section id="calculator" className="mk-section mk-section-snow">
      <div className="mk-shell">
        <div className="mk-section-head" style={{ textAlign: 'center', margin: '0 auto 56px', maxWidth: '820px' }}>
          <div className="mk-eyebrow">ROI</div>
          <h2 className="mk-h1">What missed calls<br/>are actually costing you.</h2>
          <p className="mk-sub" style={{ margin: '18px auto 0' }}>Move the sliders. Watch the number.</p>
        </div>
        <div className={`mk-calc ${visible ? 'is-visible' : ''}`} ref={calcRef}>
          <div className="mk-calc-inputs">
            <Slider label="Average ticket value"  value={ticket}   min={100} max={1000} step={50} format={(v) => '$' + v} onChange={setTicket} />
            <Slider label="Daily incoming calls"  value={calls}    min={5}   max={100}  step={5}  format={(v) => v}        onChange={setCalls} />
            <Slider label="Miss rate"             value={missRate} min={5}   max={80}   step={5}  format={(v) => v + '%'}  onChange={setMissRate} />
            <p className="mk-calc-foot">Based on {calls} calls a day at ${ticket} avg ticket with a {missRate}% miss rate.<br/>That's about {Math.round(missedDaily)} missed calls a day, {Math.round(missedMonthly)} a month.</p>
          </div>
          <div className="mk-calc-out">
            <div className="mk-calc-l">YOUR ANNUAL LEAK</div>
            <div className="mk-calc-big">{fmt(annual)}</div>
            <div className="mk-calc-sub">left on the table every year</div>
            <div className="mk-calc-divider"/>
            <div className="mk-calc-pill">
              <span className="mk-calc-pill-n">{fmt(monthly)}</span>
              <span className="mk-calc-pill-l">a month, gone</span>
            </div>
          </div>
        </div>
        <div className="mk-calc-cta">
          <a className="mk-btn-dark" href="https://cal.com/sonorai/intro-call" target="_blank" rel="noopener noreferrer">Book a strategy call <Arrow/></a>
        </div>
      </div>
    </section>
  );
}

